parameters.command:
python3 -c "
import json
end_def = json.load(open('/tmp/node_end.json'))
loop_def = json.load(open('/tmp/node_loop.json'))
script_def = json.load(open('/tmp/node_script.json'))

flow = {
  'id': '1562fcdd-92e1-4753-a265-11e33bb1e8ac',
  'version': '1.8',
  'name': 'LoopMultiply',
  'nodes': [
    {
      'id': 'start',
      'type': 'core.trigger.manual',
      'typeVersion': '1.0',
      'display': { 'label': 'Manual trigger' },
      'inputs': {
        'entryPointId': '6acd3963-ece1-41a8-9309-8d658017c586',
        'isDefaultEntryPoint': True
      }
    },
    {
      'id': 'loop1',
      'type': 'core.logic.loop',
      'typeVersion': '2.4',
      'display': { 'label': 'Loop over numbers' },
      'inputs': {
        'collection': '=js:\$vars.numbers',
        'parallel': False
      }
    },
    {
      'id': 'bodyScript',
      'type': 'core.action.script',
      'typeVersion': '1.0',
      'display': { 'label': 'Multiply current item' },
      'inputs': {
        'script': 'return \$vars.product * \$vars.loop1.currentItem;'
      },
      'parentId': 'loop1'
    },
    {
      'id': 'end1',
      'type': 'core.control.end',
      'typeVersion': '1.0',
      'display': { 'label': 'End' },
      'inputs': {},
      'outputs': {
        'product': { 'source': '=js:\$vars.product' }
      }
    }
  ],
  'edges': [
    { 'id': 'e1', 'sourceNodeId': 'start', 'sourcePort': 'output', 'targetNodeId': 'loop1', 'targetPort': 'input' },
    { 'id': 'e2', 'sourceNodeId': 'loop1', 'sourcePort': 'start', 'targetNodeId': 'bodyScript', 'targetPort': 'input' },
    { 'id': 'e3', 'sourceNodeId': 'bodyScript', 'sourcePort': 'success', 'targetNodeId': 'loop1', 'targetPort': 'continue' },
    { 'id': 'e4', 'sourceNodeId': 'loop1', 'sourcePort': 'success', 'targetNodeId': 'end1', 'targetPort': 'input' }
  ],
  'definitions': [
    {
      'nodeType': 'core.trigger.manual',
      'version': '1.0',
      'category': 'trigger',
      'description': 'Start workflow manually',
      'tags': ['trigger', 'start', 'manual'],
      'sortOrder': 40,
      'display': { 'label': 'Manual trigger', 'icon': 'play', 'shape': 'circle' },
      'handleConfiguration': [
        {
          'position': 'right',
          'handles': [
            {
              'id': 'output',
              'type': 'source',
              'handleType': 'output',
              'showButton': True,
              'constraints': { 'forbiddenTargetCategories': ['trigger'] }
            }
          ],
          'visible': True
        }
      ],
      'model': { 'type': 'bpmn:StartEvent', 'entryPointId': True },
      'outputDefinition': {
        'output': {
          'type': 'object',
          'description': 'Data passed when manually triggering the workflow.',
          'source': 'null',
          'var': 'output'
        }
      },
      'toolbarExtensions': {
        'design': {
          'actions': [
            { 'id': 'change-trigger-type', 'icon': 'square-mouse-pointer', 'label': 'Change trigger type' }
          ]
        }
      }
    },
    loop_def,
    script_def,
    end_def
  ],
  'variables': {
    'globals': [
      { 'id': 'numbers', 'direction': 'in', 'type': 'array', 'defaultValue': [13, 15, 17] },
      { 'id': 'product', 'direction': 'inout', 'type': 'number', 'defaultValue': 1 },
      { 'id': 'product_out', 'direction': 'out', 'type': 'number' }
    ],
    'nodes': [
      { 'id': 'loop1.currentItem', 'type': 'any', 'description': 'Current item in loop', 'binding': { 'nodeId': 'loop1', 'outputId': 'currentItem' } },
      { 'id': 'loop1.currentIteration', 'type': 'number', 'description': 'Current iteration number (1-based)', 'binding': { 'nodeId': 'loop1', 'outputId': 'currentIteration' } },
      { 'id': 'loop1.collection', 'type': 'array', 'description': 'Collection being iterated', 'binding': { 'nodeId': 'loop1', 'outputId': 'collection' } },
      { 'id': 'loop1.output', 'type': 'array', 'description': 'Aggregated loop results', 'binding': { 'nodeId': 'loop1', 'outputId': 'output' } },
      { 'id': 'bodyScript.output', 'type': 'object', 'description': 'Script output', 'binding': { 'nodeId': 'bodyScript', 'outputId': 'output' } },
      { 'id': 'bodyScript.error', 'type': 'object', 'description': 'Script error', 'binding': { 'nodeId': 'bodyScript', 'outputId': 'error' } }
    ],
    'variableUpdates': {
      'bodyScript': [
        { 'variableId': 'product', 'expression': '=js:\$vars.bodyScript.output' }
      ]
    }
  },
  'layout': {
    'nodes': {
      'start': { 'position': { 'x': 256, 'y': 144 }, 'size': { 'width': 96, 'height': 96 }, 'collapsed': False },
      'loop1': { 'position': { 'x': 0, 'y': 0 }, 'size': { 'width': 96, 'height': 96 }, 'collapsed': False },
      'bodyScript': { 'position': { 'x': 0, 'y': 0 }, 'size': { 'width': 96, 'height': 96 }, 'collapsed': False },
      'end1': { 'position': { 'x': 0, 'y': 0 }, 'size': { 'width': 96, 'height': 96 }, 'collapsed': False }
    }
  }
}

with open('/work/output/artifacts/skill-flow-loop-multiply/LoopMultiply/LoopMultiply/LoopMultiply.flow', 'w') as f:
    json.dump(flow, f, indent=2)
print('Written.')
"

